class Solution {
    public int findKOr(int[] nums,int k){
        int answer=0;
        for(int bit=0;bit<31;bit++){
            int count=0,mask=1<<bit;
            for(int value:nums)if((value&mask)!=0)count++;
            if(count>=k)answer|=mask;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findKOr(nums:IntArray,k:Int):Int{
        var answer=0;
        for(bit in 0 until 31){
            var count=0;
            val mask=1 shl bit;
            for(value in nums)if((value and mask)!=0)count++;
            if(count>=k)answer=answer or mask
        };
        return answer
    }
}

